    protected void createGenModelAnnotations() {
        String source = "http://www.eclipse.org/emf/2002/GenModel";
        this.addAnnotation((ENamedElement)this.communicationDirectionTypeEEnum, source, new String[]{"documentation", "Describes the communication direction. "});
        this.addAnnotation((ENamedElement)this.communicationDirectionTypeEEnum.getELiterals().get(0), source, new String[]{"documentation", "Reception (Input)"});
        this.addAnnotation((ENamedElement)this.communicationDirectionTypeEEnum.getELiterals().get(1), source, new String[]{"documentation", "Transmission (Output)"});
        this.addAnnotation((ENamedElement)this.dcmIPduEClass, source, new String[]{"documentation", "Represents the IPdus handled by Dcm. \r\n"});
        this.addAnnotation((ENamedElement)this.getDcmIPdu_DiagPduType(), source, new String[]{"documentation", "Attribute is used to distinguish a request from a response."});
        this.addAnnotation((ENamedElement)this.iPduEClass, source, new String[]{"documentation", "The IPdu (Interaction Layer Protocol Data Unit) element is used to sum up the IPdus of AUTOSAR COM, DCM and IPduM. These Pdus are routed by the PduR. \r\n\r\nIn the AUTOSAR Layered Architecture the NPdu is not a specialization of an IPdu. The NPdu is located under the IPdu to support the low-level routing of NPdus. More details can be found in the NPdu class description. "});
        this.addAnnotation((ENamedElement)this.pduEClass, source, new String[]{"documentation", "Collection of all Pdus that can be routed through a bus interface.  "});
        this.addAnnotation((ENamedElement)this.pduEClass.getEOperations().get(0), source, new String[]{"body", "return (<%org.artop.aal.common.datatypes.IntegerDatatype%>)length.clone();"});
        this.addAnnotation((ENamedElement)this.pduEClass.getEOperations().get(1), source, new String[]{"body", "length.setRadix(newLength.getRadix());\nlength.setNoOfDigits(newLength.getNoOfDigits());\nsetLength(newLength.getValue());\n"});
        this.addAnnotation((ENamedElement)this.getPdu_Length(), source, new String[]{"documentation", "Pdu length in bytes. In case of dynamic length IPdus (containing a dynamical length signal), this value indicates the maximum data length. It should be noted that in former AUTOSAR releases (Rel 2.1, Rel 3.0, Rel 3.1, Rel 4.0 Rev. 1) this parameter was defined in bits. \r\n\r\nThe Pdu length of zero bytes is allowed."});
        this.addAnnotation((ENamedElement)this.diagPduTypeEEnum, source, new String[]{"documentation", "Used to distinguish a diagnostic request from a response."});
        this.addAnnotation((ENamedElement)this.diagPduTypeEEnum.getELiterals().get(0), source, new String[]{"documentation", "Diagnostic Response"});
        this.addAnnotation((ENamedElement)this.diagPduTypeEEnum.getELiterals().get(1), source, new String[]{"documentation", "Diagnostic Request"});
        this.addAnnotation((ENamedElement)this.dynamicPartEClass, source, new String[]{"documentation", "Dynamic part of a multiplexed I-Pdu. \r\nReserved space which is used to transport varying SignalIPdus at the same position, controlled by the corresponding selectorFieldCode."});
        this.addAnnotation((ENamedElement)this.getDynamicPart_DynamicPartAlternatives(), source, new String[]{"documentation", "Com IPdu alternatives that are transmitted  in the Dynamic Part of the MultiplexedIPdu."});
        this.addAnnotation((ENamedElement)this.getDynamicPart_VariationPoint(), source, new String[]{"documentation", "This element was generated/modified due to an atpVariation stereotype."});
        this.addAnnotation((ENamedElement)this.multiplexedPartEClass, source, new String[]{"documentation", "The StaticPart and the DynamicPart have common properties. Both can be separated in multiple segments within the multiplexed PDU. "});
        this.addAnnotation((ENamedElement)this.getMultiplexedPart_SegmentPositions(), source, new String[]{"documentation", "The StaticPart and the DynamicPart can be separated in multiple segments within the multiplexed PDU. Therefore the StaticPart and\r\nthe DynamicPart can contain multiple SegmentPositions."});
        this.addAnnotation((ENamedElement)this.segmentPositionEClass, source, new String[]{"documentation", "The StaticPart and the DynamicPart can be\r\nseparated in multiple segments within the multiplexed PDU. \r\n\r\nThe ISignalIPdus are copied bit by bit into the MultiplexedIPdu. If the space of the first segment is 5 bits large than the first 5 bits of the ISignalIPdu are copied into this first segment and so on."});
        this.addAnnotation((ENamedElement)this.segmentPositionEClass.getEOperations().get(0), source, new String[]{"body", "return (<%org.artop.aal.common.datatypes.IntegerDatatype%>)segmentLength.clone();"});
        this.addAnnotation((ENamedElement)this.segmentPositionEClass.getEOperations().get(1), source, new String[]{"body", "segmentLength.setRadix(newSegmentLength.getRadix());\nsegmentLength.setNoOfDigits(newSegmentLength.getNoOfDigits());\nsetSegmentLength(newSegmentLength.getValue());\n"});
        this.addAnnotation((ENamedElement)this.segmentPositionEClass.getEOperations().get(2), source, new String[]{"body", "return (<%org.artop.aal.common.datatypes.IntegerDatatype%>)segmentPosition.clone();"});
        this.addAnnotation((ENamedElement)this.segmentPositionEClass.getEOperations().get(3), source, new String[]{"body", "segmentPosition.setRadix(newSegmentPosition.getRadix());\nsegmentPosition.setNoOfDigits(newSegmentPosition.getNoOfDigits());\nsetSegmentPosition(newSegmentPosition.getValue());\n"});
        this.addAnnotation((ENamedElement)this.getSegmentPosition_SegmentByteOrder(), source, new String[]{"documentation", "This attribute defines the order of the bytes of the segment and the packing into the MultiplexedIPdu. The byte ordering \"Little Endian\" (MostSignificantByteLast) and \"Big Endian\" (MostSignificantByteFirst) can be selected.\r\n\r\nA mix between Little Endian and Big Endian within a MultiplexedIPdu (staticPart, dynamicPart, selectorField) is not allowed. "});
        this.addAnnotation((ENamedElement)this.getSegmentPosition_SegmentLength(), source, new String[]{"documentation", "Data Length of the segment in bits. "});
        this.addAnnotation((ENamedElement)this.getSegmentPosition_SegmentPosition(), source, new String[]{"documentation", "Segments bit position relatively to the beginning of a multiplexed IPdu.\r\n\r\nNote that the absolute position of the segment in the MultiplexedIPdu is determined by the definition of the segmentByteOrder attribute of the SegmentPosition. If Big Endian is specified, the start position indicates the bit position of the most significant bit in the IPdu. If Little Endian is specified, the start position indicates the bit position of the least significant bit in the IPdu. In AUTOSAR the bit counting is always set to \"sawtooth\" and the bit order is set to \"Decreasing\"."});
        this.addAnnotation((ENamedElement)this.dynamicPartAlternativeEClass, source, new String[]{"documentation", "One of the Com IPdu alternatives that are transmitted in the Dynamic Part of the MultiplexedIPdu. The selectorFieldCode\r\nspecifies which Com IPdu is contained in the DynamicPart within a\r\ncertain transmission of a multiplexed PDU."});
        this.addAnnotation((ENamedElement)this.dynamicPartAlternativeEClass.getEOperations().get(0), source, new String[]{"body", "return (<%org.artop.aal.common.datatypes.IntegerDatatype%>)selectorFieldCode.clone();"});
        this.addAnnotation((ENamedElement)this.dynamicPartAlternativeEClass.getEOperations().get(1), source, new String[]{"body", "selectorFieldCode.setRadix(newSelectorFieldCode.getRadix());\nselectorFieldCode.setNoOfDigits(newSelectorFieldCode.getNoOfDigits());\nsetSelectorFieldCode(newSelectorFieldCode.getValue());\n"});
        this.addAnnotation((ENamedElement)this.getDynamicPartAlternative_IPdu(), source, new String[]{"documentation", "Reference to a Com IPdu which is routed to the IPduM module and is combined to a multiplexedPdu. "});
        this.addAnnotation((ENamedElement)this.getDynamicPartAlternative_InitialDynamicPart(), source, new String[]{"documentation", "Dynamic part that shall be used to initialize this multiplexed IPdu.\r\n\r\nConstraint: Only one \"DynamicPartAlternative\" in a \"DynamicPart\" shall\r\nbe the initialDynamicPart."});
        this.addAnnotation((ENamedElement)this.getDynamicPartAlternative_SelectorFieldCode(), source, new String[]{"documentation", "The selector field is part of a multiplexed IPdu. It consists of contiguous bits. The value of the selector field selects the layout of the multiplexed part of the IPdu. "});
        this.addAnnotation((ENamedElement)this.iSignalIPduEClass, source, new String[]{"documentation", "Represents the IPdus handled by Com. The ISignalIPdu assembled and disassembled in AUTOSAR COM consists of one or more signals.\r\nIn case no multiplexing is performed this IPdu is routed to/from the Interface Layer.\r\n\r\nA maximum of one dynamic length signal per IPdu is allowed.\r\n"});
        this.addAnnotation((ENamedElement)this.iSignalIPduEClass.getEOperations().get(0), source, new String[]{"body", "return (<%org.artop.aal.common.datatypes.IntegerDatatype%>)unusedBitPattern.clone();"});
        this.addAnnotation((ENamedElement)this.iSignalIPduEClass.getEOperations().get(1), source, new String[]{"body", "unusedBitPattern.setRadix(newUnusedBitPattern.getRadix());\nunusedBitPattern.setNoOfDigits(newUnusedBitPattern.getNoOfDigits());\nsetUnusedBitPattern(newUnusedBitPattern.getValue());\n"});
        this.addAnnotation((ENamedElement)this.getISignalIPdu_IPduTimingSpecifications(), source, new String[]{"documentation", "The upper multiplicity of this role has been increased to * due to resolving an atpVariation stereotype. The previous value was 1."});
        this.addAnnotation((ENamedElement)this.getISignalIPdu_ISignalToPduMappings(), source, new String[]{"documentation", "The upper multiplicity of this role has been increased to * due to resolving an atpVariation stereotype. The previous value was -1."});
        this.addAnnotation((ENamedElement)this.getISignalIPdu_PduCounters(), source, new String[]{"documentation", "The upper multiplicity of this role has been increased to * due to resolving an atpVariation stereotype. The previous value was 1."});
        this.addAnnotation((ENamedElement)this.getISignalIPdu_PduReplications(), source, new String[]{"documentation", "The upper multiplicity of this role has been increased to * due to resolving an atpVariation stereotype. The previous value was 1."});
        this.addAnnotation((ENamedElement)this.getISignalIPdu_UnusedBitPattern(), source, new String[]{"documentation", "AUTOSAR COM and AUTOSAR IPDUM are filling not used areas of an IPDU with this bit-pattern. This attribute is mandatory to avoid undefined behavior. This byte-pattern will be repeated throughout the IPdu. \r\n"});
        this.addAnnotation((ENamedElement)this.iSignalToIPduMappingEClass, source, new String[]{"documentation", "An ISignalToIPduMapping describes the mapping of ISignals to ISignalIPdus and defines the position of the ISignal within an ISignalIPdu.\r\n\r\nThis element does NOT describe signal or IPdu fan-out but is used to describe the COM Signal Gateway fan-out.  \r\nIn case the ISignal/ISignalGroup is not part of the Signal Gateway the ISignal/ISignalGroup can only be mapped into one ISignalIPdu.\r\nIn case the ISignal/ISignalGroup is part of the Signal Gateway several ISignalToIPduMappings of the same ISignal are supported."});
        this.addAnnotation((ENamedElement)this.iSignalToIPduMappingEClass.getEOperations().get(0), source, new String[]{"body", "return (<%org.artop.aal.common.datatypes.IntegerDatatype%>)startPosition.clone();"});
        this.addAnnotation((ENamedElement)this.iSignalToIPduMappingEClass.getEOperations().get(1), source, new String[]{"body", "startPosition.setRadix(newStartPosition.getRadix());\nstartPosition.setNoOfDigits(newStartPosition.getNoOfDigits());\nsetStartPosition(newStartPosition.getValue());\n"});
        this.addAnnotation((ENamedElement)this.iSignalToIPduMappingEClass.getEOperations().get(2), source, new String[]{"body", "return (<%org.artop.aal.common.datatypes.IntegerDatatype%>)updateIndicationBitPosition.clone();"});
        this.addAnnotation((ENamedElement)this.iSignalToIPduMappingEClass.getEOperations().get(3), source, new String[]{"body", "updateIndicationBitPosition.setRadix(newUpdateIndicationBitPosition.getRadix());\nupdateIndicationBitPosition.setNoOfDigits(newUpdateIndicationBitPosition.getNoOfDigits());\nsetUpdateIndicationBitPosition(newUpdateIndicationBitPosition.getValue());\n"});
        this.addAnnotation((ENamedElement)this.getISignalToIPduMapping_ISignalGroup(), source, new String[]{"documentation", "Reference to an ISignalGroup that is mapped into the SignalIPdu. \r\nIf an ISignalToIPduMapping for an ISignalGroup is defined, only the UpdateIndicationBitPosition and the transferProperty is relevant. The startPosition and the packingByteOrder shall be ignored. \r\n\r\nEach ISignal contained in the ISignalGroup shall be mapped into an IPdu by an own ISignalToIPduMapping. The references to the ISignal and to the ISignalGroup in an ISignalToIPduMapping are mutually exclusive. "});
        this.addAnnotation((ENamedElement)this.getISignalToIPduMapping_ISignal(), source, new String[]{"documentation", "Reference to a ISignal that is mapped into the ISignalIPdu. \r\n\r\nSeveral ISignalToPduMappings to the same ISignal are only relevant when the ECU handles the signal gateway. Each ISignal contained in the ISignalGroup shall be mapped into an IPdu by an own ISignalToIPduMapping. The references to the ISignal and to the ISignalGroup in an ISignalToIPduMapping are mutually exclusive. "});
        this.addAnnotation((ENamedElement)this.getISignalToIPduMapping_PackingByteOrder(), source, new String[]{"documentation", "This parameter defines the order of the bytes of the signal and the packing into the SignalIPdu. The byte ordering \"Little Endian\" (MostSignificantByteLast), \"Big Endian\" (MostSignificantByteFirst) and \"Opaque\" can be selected. For opaque data endianness conversion shall be configured to Opaque.\r\nThe value of this attribute impacts the absolute position of the signal into the SignalIPdu (see the startPosition attribute description). \r\n\r\nFor an ISignalGroup the packingByteOrder is irrelevant and shall be ignored. "});
        this.addAnnotation((ENamedElement)this.getISignalToIPduMapping_StartPosition(), source, new String[]{"documentation", "This parameter is necessary to describe the bitposition of a signal within an SignalIPdu.\r\nIt denotes the least significant bit for \"Little Endian\" and the most significant bit for \"Big Endian\" packed signals within the IPdu (see the description of the packingByteOrder attribute). In AUTOSAR the bit counting is always set to \"sawtooth\" and the bit order is set to \"Decreasing\".\r\n\r\nPlease note that the way the bytes will be actually sent on the bus does not impact this representation: they will always be seen by the software as a byte array.\r\n\r\nIf a mapping for the ISignalGroup is defined, this attribute is irrelevant and shall be ignored. "});
        this.addAnnotation((ENamedElement)this.getISignalToIPduMapping_TransferProperty(), source, new String[]{"documentation", "The triggered or triggeredOnChange,  triggeredWithoutRepetition and triggeredOnChangeWithoutRepetition transferProperty causes immediate transmission of the IPdu, except if transmission mode Periodic or transmission mode NONE is defined for the IPdu. The Pending transfer property does not cause transmission of an I-PDU.\r\n\r\nThe immediate transmission of the IPdu is caused even if only one Signal of an IPdu has the transferProperty triggered or triggeredWithoutRepetition or triggeredOnChange or triggeredOnChangeWithoutRepetition and all other Signals have the transferProperty pending.\r\n\r\nAlso for ISignals of an ISignalGroup (GroupSignals) this attribute is relevant and shall be evaluated:\r\n- If none of the ISignals belonging to the ISignalGroup have a transferProperty defined the transferProperty of the ISignalToPduMapping referring to the ISignalGroup is considered.\r\n- If at least one of the ISignals belonging to the ISignalGroup has a transferProperty defined all other ISignals belonging to the same ISignalGroup shall have a transferProperty defined as well. All of the transferProperties of the GroupSignals are considered."});
        this.addAnnotation((ENamedElement)this.getISignalToIPduMapping_UpdateIndicationBitPosition(), source, new String[]{"documentation", "The UpdateIndicationBit indicates to the receivers that the signal (or the signal group) was updated by the sender. Length is always one bit. The UpdateIndicationBitPosition attribute describes the position of the update bit within the SignalIPdu. For Signals of a ISignalGroup this attribute is irrelevant and shall be ignored. \r\n\r\nNote that the exact bit position of the updateIndicationBitPosition is linked to the value of the attribute packingByteOrder because the method of finding the bit position is different for the values mostSignificantByteFirst and mostSignificantByteLast. This means that if the value of packingByteOrder is changed while the value of updateIndicationBitPosition remains unchanged the exact bit position of updateIndicationBitPosition within the enclosing ISignalIPdu still undergoes a change."});
        this.addAnnotation((ENamedElement)this.getISignalToIPduMapping_VariationPoint(), source, new String[]{"documentation", "This element was generated/modified due to an atpVariation stereotype."});
        this.addAnnotation((ENamedElement)this.transferPropertyEnumEEnum, source, new String[]{"documentation", "Transfer Properties of a Signal. \r\n"});
        this.addAnnotation((ENamedElement)this.transferPropertyEnumEEnum.getELiterals().get(0), source, new String[]{"documentation", "The signal in the assigned IPdu is updated and a request for the IPdu's transmission is made.\r\n"});
        this.addAnnotation((ENamedElement)this.transferPropertyEnumEEnum.getELiterals().get(1), source, new String[]{"documentation", "If the signal has the TransferProperty pending, then the function Com_SendSignal shall not perform a transmission of the IPdu associated with the signal.\r\n"});
        this.addAnnotation((ENamedElement)this.transferPropertyEnumEEnum.getELiterals().get(2), source, new String[]{"documentation", "The signal in the assigned IPdu is updated and a request for the IPdus transmission is made only if the signal value is different from the already stored signal value.\r\n"});
        this.addAnnotation((ENamedElement)this.transferPropertyEnumEEnum.getELiterals().get(3), source, new String[]{"documentation", "The signal in the assigned IPdu is updated and a request for the IPdu's transmission is made. In the DIRECT/N-TIMES or MIXED transmission mode (EventControlledTiming) the IPdu will be transmitted just once without a repetition, independent of the defined NumberOfRepeats."});
        this.addAnnotation((ENamedElement)this.transferPropertyEnumEEnum.getELiterals().get(4), source, new String[]{"documentation", "The signal in the assigned IPdu is updated and a request for the IPdus transmission is made only if the signal value is different from the already stored signal value.  In the DIRECT/N-TIMES or MIXED transmission mode (EventControlledTiming) the IPdu will be transmitted just once without a repetition, independent of the defined NumberOfRepeats."});
        this.addAnnotation((ENamedElement)this.iSignalEClass, source, new String[]{"documentation", "Signal of the Interaction Layer. The RTE supports a \"signal fan-out\" where the same System Signal is sent in different SignalIPdus to multiple receivers. \r\n\r\nThe System Signal is unique per System. To support the RTE \"signal fan-out\" each SignalIPdu  contains ISignals. If the same System Signal is to be mapped into several SignalIPdus there is one ISignal needed for each ISignalToIPduMapping. \r\n\r\nISignals describe the Interface between the Precompile configured RTE and the potentially Postbuild configured Com Stack (see ECUC Parameter Mapping). \r\n\r\nIn case of the SystemSignalGroup an ISignal must be created for each SystemSignal contained in the SystemSignalGroup."});
        this.addAnnotation((ENamedElement)this.iSignalEClass.getEOperations().get(0), source, new String[]{"body", "return (<%org.artop.aal.common.datatypes.IntegerDatatype%>)length.clone();"});
        this.addAnnotation((ENamedElement)this.iSignalEClass.getEOperations().get(1), source, new String[]{"body", "length.setRadix(newLength.getRadix());\nlength.setNoOfDigits(newLength.getNoOfDigits());\nsetLength(newLength.getValue());\n"});
        this.addAnnotation((ENamedElement)this.getISignal_DataTypePolicy(), source, new String[]{"documentation", "With the aggregation of SwDataDefProps an ISignal specifies how it is represented on the network. This representation follows a particular policy. \r\n\r\nNote that this causes some redundancy which is intended and can be used to support flexible development methodology as well as subsequent integrity checks. \r\n\r\nIn particular, if the policy \"portInterfaceDefinition\" is chosen the network representation needs to be compatible to the default datatype specified in the interface. If the policy \"networkRepresentationFromComSpec\" is chosen the network representation needs to be compatible to the network representation of the ComSpec that is aggregated by the PortPrototype. \r\n\r\nIf the \"override\" policy is chosen the requirements specified in the PortInterface and in the ComSpec are not fulfilled by the networkRepresentationProps. In case the System Description doesn't use a complete Software Component Description (VFB View) the \"legacy\" policy can be chosen."});
        this.addAnnotation((ENamedElement)this.getISignal_ISignalProps(), source, new String[]{"documentation", "Additional optional ISignal properties that may be stored in different files."});
        this.addAnnotation((ENamedElement)this.getISignal_InitValue(), source, new String[]{"documentation", "Optional definition of a ISignal's initValue in case the System Description doesn't use a complete Software Component Description (VFB View). This supports the inclusion of legacy system signals. \r\n\r\nThis value can be used to configure the Signal's \"InitValue\". \r\n\r\nIf a full DataMapping exist for the SystemSignal this information may be available from a configured SenderComSpec and ReceiverComSpec. \r\nIn this case the initvalues in SenderComSpec and/or ReceiverComSpec override this optional value specification. Further restrictions apply from the RTE specification. "});
        this.addAnnotation((ENamedElement)this.getISignal_Length(), source, new String[]{"documentation", "Size of the signal in bits. The size needs to be derived from the mapped VariableDataPrototype according to the mapping of primitive DataTypes to BaseTypes as used in the RTE.\r\nIndicates maximum size for dynamic length signals. \r\n\r\nThe ISignal length of zero bits is allowed."});
        this.addAnnotation((ENamedElement)this.getISignal_NetworkRepresentationProps(), source, new String[]{"documentation", "Specification of the actual network representation. The usage of SwDataDefProps for this purpose is restricted to the attributes compuMethod and baseType. The optional baseType attributes \"memAllignment\" and \"byteOrder\" shall not be used. \r\n\r\nThe attribute \"dataTypePolicy\" in the SystemTemplate element defines whether this network representation is compatible to the default datatype specified in the PortInterface or to the network representation of the comspec. \r\n\r\nIf \"override\" is chosen by the system integrator the network representation can violate against the requirments defined in the PortInterface and in the network representation of the comspec. \r\n\r\nIn case that the System Description doesn't use a complete Software Component Description (VFB View) this element is used to configure \"ComSignalDataInvalidValue\" and the Data Semantics. \r\n\r\nIf a full DataMapping exist for the SystemSignal this information is additionally available from the mapped VariableDataElement. In this case the referenced datatypes needs to be compatible. Note that this redundancy is intended and can be used to support flexible development methodology as well as subsequent integrity checks. "});
        this.addAnnotation((ENamedElement)this.getISignal_SystemSignal(), source, new String[]{"documentation", "Reference to the System Signal that is supposed to be transmitted in the ISignal. "});
        this.addAnnotation((ENamedElement)this.systemSignalEClass, source, new String[]{"documentation", "The system signal represents the communication system's view of data exchanged between SW components which reside on different ECUs. The system signals allow to represent this communication in a flattened structure, with exactly one system signal defined for each data element prototype sent and received by connected SW component instances.\r\n\r\nIn case the System Description doesn't use a complete Software Component Description (VFB View) the data mapping of Variable Data Prototypes or Client Server Operations on SystemSignals needs not to be defined. This supports the inclusion of legacy signals. "});
        this.addAnnotation((ENamedElement)this.getSystemSignal_DynamicLength(), source, new String[]{"documentation", "The length of dynamic length signals is variable in run-time. Only a maximum length of such a signal is specified in the configuration (attribute length in ISignal element)."});
        this.addAnnotation((ENamedElement)this.systemSignalGroupEClass, source, new String[]{"documentation", "A signal group refers to a set of signals that must always be kept together. A signal group is used to guarantee the atomic transfer of AUTOSAR composite data types.  \r\n\r\nThe SystemSignalGroup defines a signal grouping on VFB level. On cluster level the Signal grouping is described by the ISignalGroup element. "});
        this.addAnnotation((ENamedElement)this.getSystemSignalGroup_SystemSignals(), source, new String[]{"documentation", "Reference to a set of SystemSignals that must always be kept together."});
        this.addAnnotation((ENamedElement)this.iSignalPropsEClass, source, new String[]{"documentation", "Additional ISignal properties that may be stored in different files."});
        this.addAnnotation((ENamedElement)this.getISignalProps_HandleOutOfRange(), source, new String[]{"documentation", "This attribute defines the outOfRangeHandling for received and sent signals."});
        this.addAnnotation((ENamedElement)this.iSignalGroupEClass, source, new String[]{"documentation", "SignalGroup of the Interaction Layer. The RTE supports a \"signal fan-out\" where the same System Signal Group is sent in different SignalIPdus to multiple receivers.   \r\n\r\nAn ISignalGroup refers to a set of ISignals that must always be kept together. A ISignalGroup represents a COM Signal Group.  \r\n\r\nTherefore it is recommended to put the ISignalGroup in the same Package as ISignals (see atp.recommendedPackage)"});
        this.addAnnotation((ENamedElement)this.getISignalGroup_ISignals(), source, new String[]{"documentation", "Reference to a set of ISignals that must always be kept together."});
        this.addAnnotation((ENamedElement)this.getISignalGroup_SystemSignalGroup(), source, new String[]{"documentation", "Reference to the SystemSignalGroup that is defined on VFB level and that is supposed to be transmitted in the ISignalGroup. "});
        this.addAnnotation((ENamedElement)this.iPduTimingEClass, source, new String[]{"documentation", "AUTOSAR COM provides the possibility to define two different TRANSMISSION MODES for each IPdu.\r\n\r\nThe Transmission Mode of an IPdu that is valid at a specific point in time is selected using the values of the signals that are mapped to this IPdu. For each IPdu a Transmission Mode Selector is defined. The Transmission Mode Selector is calculated by evaluating the conditions for a subset of signals  (class TransmissionModeCondition in the System Template).\r\n\r\nThe Transmission Mode Selector is defined to be true, if at least one Condition evaluates to true and is defined to be false, if all Conditions evaluate to false. \r\n"});
        this.addAnnotation((ENamedElement)this.getIPduTiming_MinimumDelay(), source, new String[]{"documentation", "Minimum Delay in seconds between successive transmissions of this I-PDU, independent of the Transmission Mode. "});
        this.addAnnotation((ENamedElement)this.getIPduTiming_TransmissionModeDeclaration(), source, new String[]{"documentation", "AUTOSAR COM allows configuring statically two different transmission modes for each\r\nI-PDU (True and False). The Transmission Mode Selector evaluates the conditions for a subset of signals and decides the transmission mode. It is possible to switch between the transmission modes during runtime."});
        this.addAnnotation((ENamedElement)this.getIPduTiming_VariationPoint(), source, new String[]{"documentation", "This element was generated/modified due to an atpVariation stereotype."});
        this.addAnnotation((ENamedElement)this.signalIPduReplicationEClass, source, new String[]{"documentation", "PduReplication is a form of redundancy where the data content of one ISignalIPdu (source) is transmitted inside a set of replica ISignalIPdus. These ISignalIPdus (copies) have different Pdu IDs, identical PduCounters, identical data content and are transmitted with the same frequency.\r\n"});
        this.addAnnotation((ENamedElement)this.signalIPduReplicationEClass.getEOperations().get(0), source, new String[]{"body", "return (<%org.artop.aal.common.datatypes.IntegerDatatype%>)pduReplicationVoting.clone();"});
        this.addAnnotation((ENamedElement)this.signalIPduReplicationEClass.getEOperations().get(1), source, new String[]{"body", "pduReplicationVoting.setRadix(newPduReplicationVoting.getRadix());\npduReplicationVoting.setNoOfDigits(newPduReplicationVoting.getNoOfDigits());\nsetPduReplicationVoting(newPduReplicationVoting.getValue());\n"});
        this.addAnnotation((ENamedElement)this.getSignalIPduReplication_PduReplicationVoting(), source, new String[]{"documentation", "Number of identical IPdus needed for successful voting (1-3).\r\n"});
        this.addAnnotation((ENamedElement)this.getSignalIPduReplication_ReplicaPdus(), source, new String[]{"documentation", "Reference to replica Pdus of this IPdu.\r\n"});
        this.addAnnotation((ENamedElement)this.getSignalIPduReplication_VariationPoint(), source, new String[]{"documentation", "This element was generated/modified due to an atpVariation stereotype."});
        this.addAnnotation((ENamedElement)this.signalIPduCounterEClass, source, new String[]{"documentation", "A PduCounter is included in a predefined set of Pdus and used to ensure that a sequence of Pdus is maintained. The counter is incremented when a Pdu is transmitted. The receivers check if the received Pdu is the next one in sequence. \r\n"});
        this.addAnnotation((ENamedElement)this.signalIPduCounterEClass.getEOperations().get(0), source, new String[]{"body", "return (<%org.artop.aal.common.datatypes.IntegerDatatype%>)pduCounterSize.clone();"});
        this.addAnnotation((ENamedElement)this.signalIPduCounterEClass.getEOperations().get(1), source, new String[]{"body", "pduCounterSize.setRadix(newPduCounterSize.getRadix());\npduCounterSize.setNoOfDigits(newPduCounterSize.getNoOfDigits());\nsetPduCounterSize(newPduCounterSize.getValue());\n"});
        this.addAnnotation((ENamedElement)this.signalIPduCounterEClass.getEOperations().get(2), source, new String[]{"body", "return (<%org.artop.aal.common.datatypes.IntegerDatatype%>)pduCounterStartPosition.clone();"});
        this.addAnnotation((ENamedElement)this.signalIPduCounterEClass.getEOperations().get(3), source, new String[]{"body", "pduCounterStartPosition.setRadix(newPduCounterStartPosition.getRadix());\npduCounterStartPosition.setNoOfDigits(newPduCounterStartPosition.getNoOfDigits());\nsetPduCounterStartPosition(newPduCounterStartPosition.getValue());\n"});
        this.addAnnotation((ENamedElement)this.signalIPduCounterEClass.getEOperations().get(4), source, new String[]{"body", "return (<%org.artop.aal.common.datatypes.IntegerDatatype%>)pduCounterThreshold.clone();"});
        this.addAnnotation((ENamedElement)this.signalIPduCounterEClass.getEOperations().get(5), source, new String[]{"body", "pduCounterThreshold.setRadix(newPduCounterThreshold.getRadix());\npduCounterThreshold.setNoOfDigits(newPduCounterThreshold.getNoOfDigits());\nsetPduCounterThreshold(newPduCounterThreshold.getValue());\n"});
        this.addAnnotation((ENamedElement)this.getSignalIPduCounter_PduCounterSize(), source, new String[]{"documentation", "Size of PduCounter expressed in bits. \r\nRange: 1..8\r\n"});
        this.addAnnotation((ENamedElement)this.getSignalIPduCounter_PduCounterStartPosition(), source, new String[]{"documentation", "Position of PduCounter expressed in bits. Note that PduCounter is not allowed to cross a byte border. \r\n"});
        this.addAnnotation((ENamedElement)this.getSignalIPduCounter_PduCounterThreshold(), source, new String[]{"documentation", "Threshold value of IPduCounter algorithm. See AUTOSAR COM Spec for more details. \r\n"});
        this.addAnnotation((ENamedElement)this.getSignalIPduCounter_VariationPoint(), source, new String[]{"documentation", "This element was generated/modified due to an atpVariation stereotype."});
        this.addAnnotation((ENamedElement)this.framePortEClass, source, new String[]{"documentation", "Connectors reception or send port on the referenced channel referenced by a FrameTriggering."});
        this.addAnnotation((ENamedElement)this.frameTriggeringEClass, source, new String[]{"documentation", "The FrameTriggering describes the instance of a frame sent on a channel and defines the manner of triggering (timing information) and identification of a frame on the channel, on which it is sent.\r\n\r\nFor the same frame, if FrameTriggerings exist on more than one channel of the same cluster the fan-out/in is handled by the Bus interface.  "});
        this.addAnnotation((ENamedElement)this.getFrameTriggering_FramePorts(), source, new String[]{"documentation", "References to the FramePort on every ECU of the system which sends and/or\r\nreceives the frame.\r\n\r\nReferences for both the sender and the receiver side shall be included when the system is completely defined."});
        this.addAnnotation((ENamedElement)this.getFrameTriggering_Frame(), source, new String[]{"documentation", "One frame can be triggered several times, e.g. on different channels. If a frame has no frame triggering, it won't be sent at all. A frame triggering has assigned exactly one frame, which it triggers."});
        this.addAnnotation((ENamedElement)this.getFrameTriggering_PduTriggerings(), source, new String[]{"documentation", "This property was modified due to atpVariation (DirectedAssociationPattern)."});
        this.addAnnotation((ENamedElement)this.getFrameTriggering_VariationPoint(), source, new String[]{"documentation", "This element was generated/modified due to an atpVariation stereotype."});
        this.addAnnotation((ENamedElement)this.pduTriggeringRefConditionalEClass, source, new String[]{"documentation", "This element was generated/modified due to an atpVariation stereotype."});
        this.addAnnotation((ENamedElement)this.getPduTriggeringRefConditional_VariationPoint(), source, new String[]{"documentation", "This element was generated/modified due to an atpVariation stereotype."});
        this.addAnnotation((ENamedElement)this.pduTriggeringEClass, source, new String[]{"documentation", "The PduTriggering describes on which channel the IPdu is transmitted.\r\nThe Pdu routing by the PduR is only allowed for \"IPdus\" and not for NmPdus and XcpPdus.\r\n\r\nDepending on its relation to entities such channels and clusters it can be unambiguously deduced whether a fan-out is handled by the Pdu router or the Bus Interface. If the fan-out is specified between different clusters it shall be handled by the Pdu Router. If the fan-out is specified between different channels of the same cluster it shall be handled by the Bus Interface."});
        this.addAnnotation((ENamedElement)this.getPduTriggering_IPduPorts(), source, new String[]{"documentation", "References to the IPduPort on every ECU of the system which sends and/or\r\nreceives the I-PDU.\r\n\r\nReferences for both the sender and the receiver side shall be included when the system is completely defined."});
        this.addAnnotation((ENamedElement)this.getPduTriggering_IPdu(), source, new String[]{"documentation", "Reference to the Pdu for which the PduTriggering is defined. One I-Pdu can be triggered on different channels (PduR fan-out). The Pdu routing by the PduR is only allowed for \"IPdus\" and not for NmPdus and XcpPdus. Nevertheless is the reference to the Pdu element necessary since the PduTriggering element is also used to specify the sending and receiving connections to EcuPorts."});
        this.addAnnotation((ENamedElement)this.getPduTriggering_ISignalTriggerings(), source, new String[]{"documentation", "This property was modified due to atpVariation (DirectedAssociationPattern)."});
        this.addAnnotation((ENamedElement)this.getPduTriggering_VariationPoint(), source, new String[]{"documentation", "This element was generated/modified due to an atpVariation stereotype."});
        this.addAnnotation((ENamedElement)this.iPduPortEClass, source, new String[]{"documentation", "Connectors reception or send port on the referenced channel referenced by a PduTriggering."});
        this.addAnnotation((ENamedElement)this.iSignalTriggeringRefConditionalEClass, source, new String[]{"documentation", "This element was generated/modified due to an atpVariation stereotype."});
        this.addAnnotation((ENamedElement)this.getISignalTriggeringRefConditional_VariationPoint(), source, new String[]{"documentation", "This element was generated/modified due to an atpVariation stereotype."});
        this.addAnnotation((ENamedElement)this.iSignalTriggeringEClass, source, new String[]{"documentation", "A ISignalTriggering allows an assignment of ISignals to physical channels. "});
        this.addAnnotation((ENamedElement)this.getISignalTriggering_ISignalGroup(), source, new String[]{"documentation", "This reference shall be used if an ISignalGroup is transported on the PhysicalChannel. This reference forms an XOR relationship with the ISignalTriggering-ISignal reference. \r\n\r\n"});
        this.addAnnotation((ENamedElement)this.getISignalTriggering_ISignalPorts(), source, new String[]{"documentation", "References to the ISignalPort on every ECU of the system which sends and/or receives the ISignal.\r\n\r\nReferences for both the sender and the receiver side shall be included when the system is completely defined."});
        this.addAnnotation((ENamedElement)this.getISignalTriggering_ISignal(), source, new String[]{"documentation", "This reference shall be used if an ISignal is transported on the PhysicalChannel. This reference forms an XOR relationship with the ISignalTriggering-ISignalGroup reference. ISignalTriggerings for Group Signals (ISignals contained in the ISignalGroup) shall not be defined.  \r\n\r\n"});
        this.addAnnotation((ENamedElement)this.getISignalTriggering_VariationPoint(), source, new String[]{"documentation", "This element was generated/modified due to an atpVariation stereotype."});
        this.addAnnotation((ENamedElement)this.iSignalPortEClass, source, new String[]{"documentation", "Connectors reception or send port on the referenced channel referenced by an ISignalTriggering. \r\nIf different timeouts or DataFilters for ISignals need to be specified several ISignalPorts may be created."});
        this.addAnnotation((ENamedElement)this.getISignalPort_DataFilter(), source, new String[]{"documentation", "Optional specification of  a signal COM filter at the receiver side in case that  the System Description doesn't use a complete Software Component Description (VFB View). This supports the inclusion of legacy system signals. If a full DataMapping exist for the SystemSignal this information may be available from a configured ReceiverComSpec. In this case the ReceiverComSpec overrides this optional specification."});
        this.addAnnotation((ENamedElement)this.getISignalPort_Timeout(), source, new String[]{"documentation", "Optional timeout value in seconds for the reception of the ISignal.\r\nIn case the System Description doesn't use a complete Software Component Description (VFB View). This supports the inclusion of legacy system signals.\r\n\r\nIf a full DataMapping exist for the SystemSignal this information may be available from a configured ReceiverComSpec, in this case the timeout value in ReceiverComSpec override this optional timeout specification. "});
        this.addAnnotation((ENamedElement)this.iSignalIPduGroupEClass, source, new String[]{"documentation", "The AUTOSAR COM Layer is able to start and to stop sending and receiving  configurable groups of I-Pdus during runtime. An ISignalIPduGroup contains either ISignalIPdus or ISignalIPduGroups.\r\n\r\nWhen an ISignalIPduGroup containing one or more other ISignalIPduGroups is started the containedISignalIPduGroups shall also be started. When an ISignalIPduGroup containing one or more other ISignalIPduGroups is stopped the contained ISignalIPduGroups shall also be stopped.\r\n\r\nOnly a two level hierarchy of ISignalIPdu groups is allowed. An ISignalIPdu group that is part of an ISignalIPdu group must not contain ISignalIPduGroups.\r\n"});
        this.addAnnotation((ENamedElement)this.getISignalIPduGroup_CommunicationDirection(), source, new String[]{"documentation", "This attribute determines in which direction IPdus that are contained in this IPduGroup will be transmitted (communication direction can be either In or Out)."});
        this.addAnnotation((ENamedElement)this.getISignalIPduGroup_CommunicationMode(), source, new String[]{"documentation", "This attribute defines the use-case for this ISignalIPduGroup (e.g. diagnostic, debugging etc.). For example, in a diagnostic mode all IPdus - which are not involved in diagnostic - are disabled. The use cases are not limited to a fixed enumeration and can be specified as a string. "});
        this.addAnnotation((ENamedElement)this.getISignalIPduGroup_ContainedISignalIPduGroups(), source, new String[]{"documentation", "An I-Pdu group can be included in other I-Pdu groups. Contained I-Pdu groups shall not be referenced by the EcuInstance.  "});
        this.addAnnotation((ENamedElement)this.getISignalIPduGroup_ISignalIPdus(), source, new String[]{"documentation", "This property was modified due to atpVariation (DirectedAssociationPattern)."});
        this.addAnnotation((ENamedElement)this.iSignalIPduRefConditionalEClass, source, new String[]{"documentation", "This element was generated/modified due to an atpVariation stereotype."});
        this.addAnnotation((ENamedElement)this.getISignalIPduRefConditional_VariationPoint(), source, new String[]{"documentation", "This element was generated/modified due to an atpVariation stereotype."});
        this.addAnnotation((ENamedElement)this.multiplexedIPduEClass, source, new String[]{"documentation", "A MultiplexedPdu (i.e. NOT a COM I-PDU) contains a DynamicPart, an optional StaticPart and a selectorField. In case of multiplexing this IPdu is routed between the Pdu Multiplexer and the Interface Layer. \r\n\r\nA multiplexer is used to define variable parts within an IPdu that may carry different signals. The receivers of such a IPdu can determine which signalPdus are transmitted by evaluating the selector field, which carries a unique selector code for each sub-part.  "});
        this.addAnnotation((ENamedElement)this.multiplexedIPduEClass.getEOperations().get(0), source, new String[]{"body", "return (<%org.artop.aal.common.datatypes.IntegerDatatype%>)selectorFieldLength.clone();"});
        this.addAnnotation((ENamedElement)this.multiplexedIPduEClass.getEOperations().get(1), source, new String[]{"body", "selectorFieldLength.setRadix(newSelectorFieldLength.getRadix());\nselectorFieldLength.setNoOfDigits(newSelectorFieldLength.getNoOfDigits());\nsetSelectorFieldLength(newSelectorFieldLength.getValue());\n"});
        this.addAnnotation((ENamedElement)this.multiplexedIPduEClass.getEOperations().get(2), source, new String[]{"body", "return (<%org.artop.aal.common.datatypes.IntegerDatatype%>)selectorFieldStartPosition.clone();"});
        this.addAnnotation((ENamedElement)this.multiplexedIPduEClass.getEOperations().get(3), source, new String[]{"body", "selectorFieldStartPosition.setRadix(newSelectorFieldStartPosition.getRadix());\nselectorFieldStartPosition.setNoOfDigits(newSelectorFieldStartPosition.getNoOfDigits());\nsetSelectorFieldStartPosition(newSelectorFieldStartPosition.getValue());\n"});
        this.addAnnotation((ENamedElement)this.multiplexedIPduEClass.getEOperations().get(4), source, new String[]{"body", "return (<%org.artop.aal.common.datatypes.IntegerDatatype%>)unusedBitPattern.clone();"});
        this.addAnnotation((ENamedElement)this.multiplexedIPduEClass.getEOperations().get(5), source, new String[]{"body", "unusedBitPattern.setRadix(newUnusedBitPattern.getRadix());\nunusedBitPattern.setNoOfDigits(newUnusedBitPattern.getNoOfDigits());\nsetUnusedBitPattern(newUnusedBitPattern.getValue());\n"});
        this.addAnnotation((ENamedElement)this.getMultiplexedIPdu_DynamicParts(), source, new String[]{"documentation", "The upper multiplicity of this role has been increased to * due to resolving an atpVariation stereotype. The previous value was 1."});
        this.addAnnotation((ENamedElement)this.getMultiplexedIPdu_SelectorFieldByteOrder(), source, new String[]{"documentation", "This attribute defines the order of the bytes of the selectorField and the packing into the MultiplexedIPdu. The byte ordering \"Little Endian\" (MostSignificantByteLast) and \"Big Endian\" (MostSignificantByteFirst) can be selected.\r\nA mix between Little Endian and Big Endian within a MultiplexedIPdu (staticPart, dynamicPart, selectorField) is not allowed. \r\n\r\nIn a complete System Description this attribute is mandatory. If a MultiplexedPdu is received by a Pdu Gateway and is not delivered to the IPduM but routed directly to a bus interface then the content of the MulitplexedPdu doesn't need to be described in the System Extract/Ecu Extract. To support this use case the multiplicity is set to 0..1."});
        this.addAnnotation((ENamedElement)this.getMultiplexedIPdu_SelectorFieldLength(), source, new String[]{"documentation", "The size in bits of the selector field shall be configurable in a range of 0-2031 bits. \r\nIn a complete System Description this attribute is mandatory. If a MultiplexedPdu is received by a Pdu Gateway and is not delivered to the IPduM but routed directly to a bus interface then the content of the MulitplexedPdu doesn't need to be described in the System Extract/Ecu Extract. To support this use case the multiplicity is set to 0..1."});
        this.addAnnotation((ENamedElement)this.getMultiplexedIPdu_SelectorFieldStartPosition(), source, new String[]{"documentation", "This parameter is necessary to describe the position of the selector field within the IPdu.\r\n\r\nNote that the absolute position of the selectorField in the MultiplexedIPdu is determined by the definition of the selectorFieldByteOrder attribute of the Multiplexed Pdu. If Big Endian is specified, the start position indicates\r\nthe bit position of the most significant bit in the IPdu. If Little Endian is specified, the start position indicates the bit position of the least significant bit in the IPdu. In AUTOSAR the bit counting is always set to \"sawtooth\" and the bit order is set to \"Decreasing\".\r\n\r\nIn a complete System Description this attribute is mandatory. If a MultiplexedPdu is received by a Pdu Gateway and is not delivered to the IPduM but routed directly to a bus interface then the content of the MulitplexedPdu doesn't need to be described in the System Extract/Ecu Extract. To support this use case the multiplicity is set to 0..1."});
        this.addAnnotation((ENamedElement)this.getMultiplexedIPdu_StaticParts(), source, new String[]{"documentation", "The upper multiplicity of this role has been increased to * due to resolving an atpVariation stereotype. The previous value was 1."});
        this.addAnnotation((ENamedElement)this.getMultiplexedIPdu_TriggerMode(), source, new String[]{"documentation", "IPduM can be configured to send a transmission request for the new multiplexed IPdu to the PDU-Router because of the trigger conditions/ modes that are described in the TriggerMode enumeration.\r\n\r\nIn a complete System Description this attribute is mandatory. If a MultiplexedPdu is received by a Pdu Gateway and is not delivered to the IPduM but routed directly to a bus interface then the content of the MulitplexedPdu doesn't need to be described in the System Extract/Ecu Extract. To support this use case the multiplicity is set to 0..1.\r\n"});
        this.addAnnotation((ENamedElement)this.getMultiplexedIPdu_UnusedBitPattern(), source, new String[]{"documentation", "AUTOSAR COM and AUTOSAR IPDUM are filling not used areas of an IPdu with this bit-pattern. This attribute is mandatory to avoid undefined behavior. This byte-pattern will be repeated throughout the IPdu. \r\n\r\nIn a complete System Description this attribute is mandatory. If a MultiplexedPdu is received by a Pdu Gateway and is not delivered to the IPduM but routed directly to a bus interface then the content of the MulitplexedPdu doesn't need to be described in the System Extract/Ecu Extract. To support this use case the multiplicity is set to 0..1.\r\n"});
        this.addAnnotation((ENamedElement)this.triggerModeEEnum, source, new String[]{"documentation", "IPduM can be configured to send a transmission request for the new multiplexed I-PDU to the PDU-Router because of conditions/ modes."});
        this.addAnnotation((ENamedElement)this.triggerModeEEnum.getELiterals().get(0), source, new String[]{"documentation", "IPduM does not trigger transmission because of receiving anything of this IPdu in case of TriggerTransmit. "});
        this.addAnnotation((ENamedElement)this.triggerModeEEnum.getELiterals().get(1), source, new String[]{"documentation", "IPduM sends a transmission request to the PduR if a static part is received."});
        this.addAnnotation((ENamedElement)this.triggerModeEEnum.getELiterals().get(2), source, new String[]{"documentation", "IPduM sends a transmission request to the PduR if a dynamic part is received."});
        this.addAnnotation((ENamedElement)this.triggerModeEEnum.getELiterals().get(3), source, new String[]{"documentation", "IPduM sends a transmission request to the PduR if a static or dynamic part is received."});
        this.addAnnotation((ENamedElement)this.staticPartEClass, source, new String[]{"documentation", "Some parts/signals of the I-PDU may be the same regardless of the selector field. Such a part is called static part. The static part is optional. "});
        this.addAnnotation((ENamedElement)this.getStaticPart_IPdu(), source, new String[]{"documentation", "Reference to a Com IPdu which is routed to the IPduM module and is combined to a multiplexedPdu. "});
        this.addAnnotation((ENamedElement)this.getStaticPart_VariationPoint(), source, new String[]{"documentation", "This element was generated/modified due to an atpVariation stereotype."});
        this.addAnnotation((ENamedElement)this.nmPduEClass, source, new String[]{"documentation", "Network Management Pdu\r\n"});
        this.addAnnotation((ENamedElement)this.nmPduEClass.getEOperations().get(0), source, new String[]{"body", "return (<%org.artop.aal.common.datatypes.IntegerDatatype%>)unusedBitPattern.clone();"});
        this.addAnnotation((ENamedElement)this.nmPduEClass.getEOperations().get(1), source, new String[]{"body", "unusedBitPattern.setRadix(newUnusedBitPattern.getRadix());\nunusedBitPattern.setNoOfDigits(newUnusedBitPattern.getNoOfDigits());\nsetUnusedBitPattern(newUnusedBitPattern.getValue());\n"});
        this.addAnnotation((ENamedElement)this.getNmPdu_ISignalToIPduMappings(), source, new String[]{"documentation", "This optional aggregation is used to describe NmUserData that is transmitted in the NmPdu.  "});
        this.addAnnotation((ENamedElement)this.getNmPdu_NmDataInformation(), source, new String[]{"documentation", "Defines if the Pdu contains NM Data.\r\n"});
        this.addAnnotation((ENamedElement)this.getNmPdu_NmVoteInformation(), source, new String[]{"documentation", "Defines if the Pdu contains NM Vote information.\r\n"});
        this.addAnnotation((ENamedElement)this.getNmPdu_UnusedBitPattern(), source, new String[]{"documentation", "AUTOSAR COM is filling not used areas of an Pdu with this bit-pattern. This attribute can only be used if the nmDataInformation attribute is set to true. "});
        this.addAnnotation((ENamedElement)this.nPduEClass, source, new String[]{"documentation", "This is a Pdu of the Transport Layer.\r\nThe main purpose of the TP Layer is to segment and reassemble IPdus. \r\n\r\nIn case of a Pdu Gateway when the source and the target network are of the same kind (e.g. Can-to-Can routing) it is possible to optimize the routing. The incoming NPdu can be directly forwarded to the PduR and then be sent on the outbound bus without any (resource consuming) TP module involvement. To support this use case the NPdu is located under the IPdu. But in the AUTOSAR Layered Architecture the NPdu is not a specialization of an IPdu. \r\n"});
        this.addAnnotation((ENamedElement)this.pdurIPduGroupEClass, source, new String[]{"documentation", "The AUTOSAR PduR will enable and disable the sending of configurable groups of IPdus during runtime according to the AUTOSAR PduR specification.  \r\n"});
        this.addAnnotation((ENamedElement)this.getPdurIPduGroup_CommunicationMode(), source, new String[]{"documentation", "This attribute defines the use-case for this PduRIPduGroup. For example, in a diagnostic mode all IPdus - which are not involved in diagnostic - are disabled. The use cases are not limited to a fixed enumeration and can be specified as a string."});
        this.addAnnotation((ENamedElement)this.getPdurIPduGroup_IPdus(), source, new String[]{"documentation", "This property was modified due to atpVariation (DirectedAssociationPattern)."});
        this.addAnnotation((ENamedElement)this.pduToFrameMappingEClass, source, new String[]{"documentation", "A PduToFrameMapping defines the composition of Pdus in each frame. "});
        this.addAnnotation((ENamedElement)this.pduToFrameMappingEClass.getEOperations().get(0), source, new String[]{"body", "return (<%org.artop.aal.common.datatypes.IntegerDatatype%>)startPosition.clone();"});
        this.addAnnotation((ENamedElement)this.pduToFrameMappingEClass.getEOperations().get(1), source, new String[]{"body", "startPosition.setRadix(newStartPosition.getRadix());\nstartPosition.setNoOfDigits(newStartPosition.getNoOfDigits());\nsetStartPosition(newStartPosition.getValue());\n"});
        this.addAnnotation((ENamedElement)this.pduToFrameMappingEClass.getEOperations().get(2), source, new String[]{"body", "return (<%org.artop.aal.common.datatypes.IntegerDatatype%>)updateIndicationBitPosition.clone();"});
        this.addAnnotation((ENamedElement)this.pduToFrameMappingEClass.getEOperations().get(3), source, new String[]{"body", "updateIndicationBitPosition.setRadix(newUpdateIndicationBitPosition.getRadix());\nupdateIndicationBitPosition.setNoOfDigits(newUpdateIndicationBitPosition.getNoOfDigits());\nsetUpdateIndicationBitPosition(newUpdateIndicationBitPosition.getValue());\n"});
        this.addAnnotation((ENamedElement)this.getPduToFrameMapping_PackingByteOrder(), source, new String[]{"documentation", "This attribute defines the order of the bytes of the Pdu and the packing into the Frame. The byte ordering \"Little Endian\" (MostSignificantByteLast) and \"Big Endian\" (MostSignificantByteFirst) can be selected.\r\n\r\nA mix between Little Endian and Big Endian within a Frame is not allowed (all PduToFrameMappings within a Frame must have the same packingByteOrder). "});
        this.addAnnotation((ENamedElement)this.getPduToFrameMapping_Pdu(), source, new String[]{"documentation", "Reference to a I-Pdu, N-Pdu or NmPdu that is transmitted in the Frame. "});
        this.addAnnotation((ENamedElement)this.getPduToFrameMapping_StartPosition(), source, new String[]{"documentation", "This parameter is necessary to describe the byteposition of a Pdu within a Frame. \r\n\r\nNote that the absolute position of the Pdu in the Frame is determined by the definition of the packingByteOrder attribute. If Big Endian is specified, the start position indicates the bit position of the most significant bit in the Frame. If Little Endian is specified, the start position indicates the bit position of the least significant bit in the Frame."});
        this.addAnnotation((ENamedElement)this.getPduToFrameMapping_UpdateIndicationBitPosition(), source, new String[]{"documentation", "Indication to the receivers that the corresponding Pdu was updated by the sender. \r\nThis attribute describes the position of the update bit in the frame that aggregates this PDUToFrameMapping. Length is always one bit.\r\n\r\nNote that the exact bit position of the updateIndicationBitPosition is linked to the value of the attribute packingByteOrder because the method of finding the bit position is different for the values mostSignificantByteFirst and mostSignificantByteLast. This means that if the value of packingByteOrder is changed while the value of updateIndicationBitPosition remains unchanged the exact bit position of updateIndicationBitPosition within the enclosing Frame still undergoes a change."});
        this.addAnnotation((ENamedElement)this.getPduToFrameMapping_VariationPoint(), source, new String[]{"documentation", "This element was generated/modified due to an atpVariation stereotype."});
        this.addAnnotation((ENamedElement)this.userDefinedIPduEClass, source, new String[]{"documentation", "UserDefinedIPdu allows to describe PDU-based communication over Complex Communication Drivers. If a new BSW module is added above the PduR (e.g. a Diagnostic Service ) then this IPdu element shall be used to describe the communication. "});
        this.addAnnotation((ENamedElement)this.getUserDefinedIPdu_CddType(), source, new String[]{"documentation", "This attribute defines the CDD that transmits or receives the UserDefinedPdu. If several CDDs are defined this attribute is used to distinguish between them. "});
        this.addAnnotation((ENamedElement)this.userDefinedPduEClass, source, new String[]{"documentation", "UserDefinedPdu allows to describe PDU-based communication over Complex Communication Drivers. If a new BSW module is added above the BusIf (e.g. a new Nm module) then this Pdu element shall be used to describe the communication. "});
        this.addAnnotation((ENamedElement)this.getUserDefinedPdu_CddType(), source, new String[]{"documentation", "This attribute defines the CDD that transmits or receives the UserDefinedIPdu. If several CDDs are defined this attribute is used to distinguish between them. "});
        this.addAnnotation((ENamedElement)this.xcpPduEClass, source, new String[]{"documentation", "AUTOSAR XCP Pdu"});
        this.addAnnotation((ENamedElement)this.frameEClass, source, new String[]{"documentation", "Data frame which is sent over a communication medium. This element describes the pure Layout of a frame sent on a channel."});
        this.addAnnotation((ENamedElement)this.frameEClass.getEOperations().get(0), source, new String[]{"body", "return (<%org.artop.aal.common.datatypes.IntegerDatatype%>)frameLength.clone();"});
        this.addAnnotation((ENamedElement)this.frameEClass.getEOperations().get(1), source, new String[]{"body", "frameLength.setRadix(newFrameLength.getRadix());\nframeLength.setNoOfDigits(newFrameLength.getNoOfDigits());\nsetFrameLength(newFrameLength.getValue());\n"});
        this.addAnnotation((ENamedElement)this.getFrame_FrameLength(), source, new String[]{"documentation", "The used length (in bytes)  of the referencing frame. Should not be confused with a static byte length reserved for each frame by some platforms (e.g. FlexRay). \r\n\r\nThe frameLength of zero bytes is allowed."});
        this.addAnnotation((ENamedElement)this.getFrame_PduToFrameMappings(), source, new String[]{"documentation", "The upper multiplicity of this role has been increased to * due to resolving an atpVariation stereotype. The previous value was -1."});
    }

